{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_012EUzeP7j2VSSKbWTReGWCA","type":"tool_result","content":"     1→from neo4j import GraphDatabase
     2→import os
     3→import logging
     4→from dotenv import load_dotenv
     5→
     6→
     7→def import_got_data(uri, username, password):
     8→    driver = GraphDatabase.driver(uri, auth=(username, password))
     9→
    10→    with driver.session() as session:
    11→        # Create constraints separately
    12→        session.run("""
    13→        CALL apoc.schema.assert(
    14→        {Location:['name'],Region:['name']},
    15→        {Battle:['name'],Person:['name'],House:['name']});        
    16→        """)
    17→        
    18→        session.run("""
    19→        LOAD CSV WITH HEADERS FROM 
    20→        "https://raw.githubusercontent.com/tomasonjo/neo4j-game-of-thrones/master/data/battles.csv" as row
    21→        //merge node labeled Battle 
    22→        MERGE (b:Battle{name:row.name})
    23→        ON CREATE SET b.year = toInteger(row.year),
    24→                    b.summer = row.summer,
    25→                    b.major_death = row.major_death,
    26→                    b.major_capture = row.major_capture,
    27→                    b.note = row.note,
    28→                    b.battle_type = row.battle_type,
    29→                    b.attacker_size = toInteger(row.attacker_size),
    30→                    b.defender_size = toInteger(row.defender_size)
    31→        """)
    32→
    33→        session.run("""
    34→        LOAD CSV WITH HEADERS FROM 
    35→        "https://raw.githubusercontent.com/tomasonjo/neo4j-game-of-thrones/master/data/battles.csv" as row
    36→        // there is only attacker_outcome in the data, 
    37→        // so we do a CASE statement for defender_outcome
    38→        WITH row,
    39→        case when row.attacker_outcome = "win" THEN "loss" ELSE "win" END as defender_outcome
    40→        // match the battle
    41→        MATCH (b:Battle{name:row.name})
    42→        // all battles have atleast one attacker so we don't have to use foreach trick
    43→        MERGE (attacker1:House{name:row.attacker_1}) 
    44→        MERGE (attacker1)-[a1:ATTACKER]->(b) 
    45→        ON CREATE SET a1.outcome = row.attacker_outcome
    46→
    47→        // When we want to skip null values we can use foreach trick
    48→        FOREACH
    49→        (ignoreMe IN CASE WHEN row.defender_1 is not null THEN [1] ELSE [] END | 
    50→            MERGE (defender1:House{name:row.defender_1})
    51→            MERGE (defender1)-[d1:DEFENDER]->(b)
    52→            ON CREATE SET d1.outcome = defender_outcome)
    53→        FOREACH
    54→        (ignoreMe IN CASE WHEN row.defender_2 is not null THEN [1] ELSE [] END | 
    55→            MERGE (defender2:House{name:row.defender_2})
    56→            MERGE (defender2)-[d2:DEFENDER]->(b)
    57→            ON CREATE SET d2.outcome = defender_outcome)
    58→        FOREACH
    59→        (ignoreMe IN CASE WHEN row.attacker_2 is not null THEN [1] ELSE [] END | 
